content.css:
/* ========================================================================== */
/* BFUSION Task KPI Board                                                     */
/* ========================================================================== */
.bfusion-root.tkb-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #ffffff;
  position: relative;
  color: #0f172a;
  padding-bottom: 24px;
  /* license badge clear-zone */
}
.bfusion-root.tkb-root *,
.bfusion-root.tkb-root *:before,
.bfusion-root.tkb-root *:after {
  box-sizing: border-box;
}
/* ========================================================================== */
/* Shell + Board                                                              */
/* ========================================================================== */
.tkb-shell {
  width: 100%;
  height: 100%;
  overflow: auto;
}
.tkb-board {
  display: flex;
  flex-direction: column;
  min-height: 100%;
  padding: 12px 16px 4px;
}
.tkb-body {
  display: flex;
  flex-direction: row;
  gap: 12px;
  align-items: stretch;
  flex: 1;
  min-height: 0;
}
.tkb-main {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
/* ========================================================================== */
/* Header                                                                     */
/* ========================================================================== */
.tkb-head {
  margin-bottom: 8px;
}
.tkb-head__titlebar {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
}
.tkb-head__titles {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.tkb-head__title {
  font-size: 14px;
  font-weight: 600;
  color: #0f172a;
  line-height: 1.2;
}
.tkb-head__subtitle {
  font-size: 11px;
  color: #94a3b8;
  margin-top: 1px;
}
.tkb-head__status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  background: #f8fafc;
  font-size: 11px;
  font-weight: 500;
  color: #475569;
}
.tkb-head__status-text {
  white-space: nowrap;
}
.tkb-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}
.tkb-pulse--healthy {
  background: #10b981;
  box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.6);
  animation: tkb-pulse 2.4s infinite;
}
.tkb-pulse--warning {
  background: #f59e0b;
  box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.6);
  animation: tkb-pulse 1.6s infinite;
}
.tkb-pulse--critical {
  background: #ef4444;
  box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.6);
  animation: tkb-pulse 1s infinite;
}
@keyframes tkb-pulse {
  0% {
    box-shadow: 0 0 0 0 currentColor;
    opacity: 1;
  }
  70% {
    box-shadow: 0 0 0 8px transparent;
    opacity: 0.8;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
    opacity: 1;
  }
}
.tkb-head__spacer {
  flex: 1;
}
.tkb-info-btn {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid #e5e7eb;
  background: #ffffff;
  color: #475569;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
  padding: 0;
  flex-shrink: 0;
}
.tkb-info-btn:hover {
  border-color: #E8612A;
  color: #E8612A;
}
.tkb-info-btn__i {
  font-family: Georgia, "Times New Roman", serif;
  font-style: italic;
  font-weight: 700;
  font-size: 13px;
  line-height: 1;
}
/* ========================================================================== */
/* Hero (Ring + Big counts)                                                   */
/* ========================================================================== */
.tkb-hero {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 20px;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 16px 20px;
}
.tkb-hero__ring {
  flex-shrink: 0;
}
.tkb-hero__ring svg {
  display: block;
}
.tkb-hero__ring-pct {
  font-size: 26px;
  font-weight: 700;
  font-family: "Segoe UI", system-ui, sans-serif;
}
.tkb-hero__ring-sub {
  font-size: 10px;
  fill: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: 600;
}
.tkb-hero__counts {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 24px;
  flex: 1;
  min-width: 0;
}
.tkb-hero__count {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  border-left: 1px solid #e5e7eb;
  padding-left: 20px;
}
.tkb-hero__count:first-child {
  border-left: 0;
  padding-left: 0;
}
.tkb-hero__count-value {
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  color: #0f172a;
  letter-spacing: -0.5px;
}
.tkb-hero__count-label {
  font-size: 11px;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
  margin-top: 6px;
}
.tkb-hero__count-sub {
  font-size: 11px;
  color: #94a3b8;
  margin-top: 2px;
}
/* ========================================================================== */
/* KPI Strip                                                                  */
/* ========================================================================== */
.tkb-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}
.tkb-tile {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-top: 3px solid var(--tile-accent, #E8612A);
  border-radius: 8px;
  padding: 10px 12px;
  min-width: 0;
  transition: box-shadow 0.15s ease, transform 0.15s ease;
}
.tkb-tile:hover {
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.06);
  transform: translateY(-1px);
}
.tkb-tile__label {
  font-size: 10.5px;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
  margin-bottom: 4px;
}
.tkb-tile__value {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.1;
  color: var(--tile-accent, #0f172a);
  letter-spacing: -0.3px;
}
.tkb-tile__sub {
  font-size: 10.5px;
  color: #94a3b8;
  margin-top: 3px;
  line-height: 1.35;
}
/* ========================================================================== */
/* Health Bar                                                                 */
/* ========================================================================== */
.tkb-healthbar {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 10px 14px 12px;
}
.tkb-healthbar__title {
  font-size: 10.5px;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
  margin-bottom: 8px;
}
.tkb-healthbar__track {
  display: flex;
  height: 18px;
  border-radius: 4px;
  overflow: hidden;
  background: #eef1f4;
}
.tkb-healthbar__seg {
  height: 100%;
  transition: width 0.4s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  cursor: default;
}
.tkb-healthbar__seg:hover {
  opacity: 0.85;
}
.tkb-healthbar__seg-label {
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
}
.tkb-healthbar__legend {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 8px;
}
.tkb-legend {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: #475569;
}
.tkb-legend__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.tkb-legend__label {
  font-weight: 500;
}
.tkb-legend__count {
  color: #0f172a;
  font-weight: 700;
  margin-left: 2px;
}
/* ========================================================================== */
/* Attention Banner                                                           */
/* ========================================================================== */
.tkb-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-radius: 8px;
  font-size: 12px;
  line-height: 1.4;
  border: 1px solid transparent;
}
.tkb-banner__icon {
  font-size: 16px;
  flex-shrink: 0;
  line-height: 1;
  color: var(--banner-color, #475569);
}
.tkb-banner__text {
  color: #0f172a;
}
.tkb-banner__text strong {
  color: var(--banner-color, #0f172a);
  font-weight: 700;
}
.tkb-banner--ok {
  background: rgba(5, 150, 105, 0.06);
  border-color: rgba(5, 150, 105, 0.2);
}
.tkb-banner--warning {
  background: rgba(217, 119, 6, 0.06);
  border-color: rgba(217, 119, 6, 0.22);
}
.tkb-banner--critical {
  background: rgba(220, 38, 38, 0.06);
  border-color: rgba(220, 38, 38, 0.22);
}
/* ========================================================================== */
/* Insight Rail                                                               */
/* ========================================================================== */
.tkb-rail {
  flex: 0 0 240px;
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 10px 12px 12px;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow-y: auto;
}
.tkb-rail--collapsed {
  flex: 0 0 16px;
  padding: 0;
  cursor: pointer;
  background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.tkb-rail--collapsed:hover {
  background: #f1f5f9;
}
.tkb-rail__arrow {
  color: #94a3b8;
  font-size: 10px;
  writing-mode: vertical-rl;
}
.tkb-rail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}
.tkb-rail__title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #475569;
}
.tkb-rail__toggle {
  width: 18px;
  height: 18px;
  border-radius: 4px;
  border: 0;
  background: transparent;
  color: #94a3b8;
  font-size: 10px;
  cursor: pointer;
  padding: 0;
}
.tkb-rail__toggle:hover {
  color: #E8612A;
  background: rgba(232, 97, 42, 0.08);
}
.tkb-rail__divider {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed #e5e7eb;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #94a3b8;
  margin-bottom: 6px;
}
.tkb-rail__group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.tkb-insight {
  display: flex;
  flex-direction: row;
  gap: 8px;
  padding: 8px 10px;
  background: #ffffff;
  border-radius: 6px;
  border-left: 3px solid #e5e7eb;
}
.tkb-insight--info {
  border-left-color: #3b82f6;
}
.tkb-insight--success {
  border-left-color: #059669;
}
.tkb-insight--warning {
  border-left-color: #d97706;
}
.tkb-insight--critical {
  border-left-color: #dc2626;
}
.tkb-insight__icon {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #f8fafc;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: #0f172a;
  flex-shrink: 0;
}
.tkb-insight--info .tkb-insight__icon {
  background: rgba(59, 130, 246, 0.1);
  color: #2563eb;
}
.tkb-insight--success .tkb-insight__icon {
  background: rgba(5, 150, 105, 0.1);
  color: #059669;
}
.tkb-insight--warning .tkb-insight__icon {
  background: rgba(217, 119, 6, 0.1);
  color: #d97706;
}
.tkb-insight--critical .tkb-insight__icon {
  background: rgba(220, 38, 38, 0.1);
  color: #dc2626;
}
.tkb-insight__body {
  min-width: 0;
  flex: 1;
}
.tkb-insight__label {
  font-size: 10.5px;
  font-weight: 700;
  color: #0f172a;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.tkb-insight__text {
  font-size: 11px;
  color: #475569;
  line-height: 1.4;
  margin-top: 2px;
}
/* ========================================================================== */
/* Info Popover                                                               */
/* ========================================================================== */
.tkb-info-pop {
  position: absolute;
  inset: 0;
  display: none;
  z-index: 30;
  background: rgba(15, 23, 42, 0.18);
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.tkb-info-pop[data-state="shown"] {
  display: flex;
}
.tkb-info-pop__inner {
  background: #ffffff;
  border-radius: 10px;
  max-width: 420px;
  width: 100%;
  padding: 18px 22px 20px;
  box-shadow: 0 12px 32px rgba(15, 23, 42, 0.2);
  position: relative;
  max-height: 86%;
  overflow-y: auto;
}
.tkb-info-pop__close {
  position: absolute;
  top: 8px;
  right: 10px;
  border: 0;
  background: transparent;
  font-size: 18px;
  cursor: pointer;
  color: #94a3b8;
  line-height: 1;
  padding: 4px 6px;
}
.tkb-info-pop__close:hover {
  color: #0f172a;
}
.tkb-info-pop__title {
  font-size: 14px;
  font-weight: 700;
  color: #0f172a;
  padding-bottom: 6px;
  border-bottom: 2px solid #E8612A;
  margin-bottom: 10px;
}
.tkb-info-pop__desc {
  font-size: 12px;
  color: #475569;
  line-height: 1.5;
  margin-bottom: 12px;
}
.tkb-info-pop__subhead {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}
.tkb-info-pop__list {
  margin: 0;
  padding-left: 18px;
}
.tkb-info-pop__list li {
  font-size: 11.5px;
  color: #475569;
  line-height: 1.5;
  margin-bottom: 4px;
}
/* ========================================================================== */
/* Responsive breakpoints                                                     */
/* ========================================================================== */
.tkb-root.tkb-medium .tkb-strip {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.tkb-root.tkb-medium .tkb-rail {
  flex-basis: 200px;
}
.tkb-root.tkb-medium .tkb-hero__count-value {
  font-size: 24px;
}
.tkb-root.tkb-medium .tkb-hero__ring svg {
  width: 110px;
  height: 110px;
}
.tkb-root.tkb-narrow {
  padding-bottom: 28px;
}
.tkb-root.tkb-narrow .tkb-body {
  flex-direction: column;
}
.tkb-root.tkb-narrow .tkb-rail {
  flex-basis: auto;
  position: absolute;
  right: 8px;
  top: 60px;
  bottom: 32px;
  width: 220px;
  z-index: 8;
  box-shadow: -6px 0 16px rgba(15, 23, 42, 0.08);
}
.tkb-root.tkb-narrow .tkb-rail.tkb-rail--collapsed {
  position: absolute;
  right: 0;
  top: 60px;
  bottom: 32px;
  width: 16px;
}
.tkb-root.tkb-narrow .tkb-strip {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.tkb-root.tkb-narrow .tkb-hero {
  flex-direction: column;
  align-items: flex-start;
}
.tkb-root.tkb-narrow .tkb-hero__counts {
  width: 100%;
  gap: 14px;
}
.tkb-root.tkb-narrow .tkb-hero__count {
  padding-left: 12px;
}
.tkb-root.tkb-narrow .tkb-hero__count:first-child {
  padding-left: 0;
}
.tkb-root.tkb-narrow .tkb-hero__count-value {
  font-size: 22px;
}
/* ========================================================================== */
/* Landing page                                                               */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge & Watermark                                                  */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
